window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-75971e761f72195b"]={"versions": [{"id": "FIG-75971e761f72195b", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (<code>act FrTSyn Time Master Timesync Message Transmission</code>).</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, BSW-Modul <code>FrTSyn</code> (FlexRay Time Synchronization, Spezifikation <em>AUTOSAR_CP_SWS_TimeSyncOverFlexRay</em>, Release R23-11).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der zyklischen Sende-Arbitrierungslogik innerhalb der Master-Funktion (<code>FrTSyn_MainFunction</code>). Steuert die zeitliche Entprellung, Bestätigungsverarbeitung sowie die Entscheidung zwischen ereignisgesteuerter (<em>Immediate</em>) und periodischer (<em>Cyclic</em>) Übertragung von Synchronisations- und Offset-Nachrichten (<code>SYNC</code> / <code>OFS</code>) pro Time Domain auf den FlexRay-Bus.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Modulgrenzen:</strong></li>\n<li><strong>FrTSyn Time Master:</strong> Führende Instanz des Zustands-/Aktivitätsablaufs.</li>\n<li><strong>StbM (Synchronized Time-Base Manager):</strong> Bereitsteller der Master-Zeitbasis über <code>timeBaseStatus</code> und <code>timeBaseUpdateCounter</code>.</li>\n<li><strong>FrIf / FlexRay-Treiber:</strong> Untere Schicht zur PDU-Aussendung und Rückmeldung (<code>TxConfirmation</code>).</li>\n<li><strong>Konfigurationsparameter (statisch / BSW-Konfiguration):</strong></li>\n<li><code>FrTSynImmediateTimeSync</code> (<code>Boolean</code>): Aktiviert die ereignisbasierte Sofort-Übertragung bei Zeitbasis-Updates.</li>\n<li><code>FrTSynGlobalTimeDebounceTime</code> (<code>uint16</code>/<code>uint32</code>): Mindestabstand (Entprellzeit in MainFunction-Ticks) zwischen zwei Sendevorgängen.</li>\n<li><code>FrTSynGlobalTimeTxPeriod</code> (<code>uint16</code>/<code>uint32</code>): Zykluszeit für die periodische Synchronisation.</li>\n<li><code>FrTSynCyclicMsgResumeTime</code> (<code>uint16</code>/<code>uint32</code>): Wartezeit nach einer Sofortaussendung vor Reaktivierung des zyklischen Sendeintervalls.</li>\n<li><strong>Laufzeitvariablen (instanziiert pro <code>TimeDomain</code> / <code>timeBaseId</code>):</strong></li>\n<li><code>cyclicMsgResumeCounter[TimeDomain]</code>: Zähler für die Aussetzzeit des zyklischen Sendens.</li>\n<li><code>debounceCounter[TimeDomain]</code>: Sperrzähler zur Busentlastung.</li>\n<li><code>cyclicCounter[TimeDomain]</code>: Dekrementierender Zähler der regulären Zykluszeit.</li>\n<li><code>timeBaseUpdateCounter[timeBaseId]</code>: Vom StbM inkrementierter Änderungszähler.</li>\n<li><code>timeBaseStatus[timeBaseId]</code>: Bitmaske der Zeitbasis, ausgewertet auf das Flag <code>GLOBAL_TIME_BASE</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf entspricht einem Zyklus der <code>FrTSyn_MainFunction</code> für eine spezifische <code>TimeDomain</code>:</p>\n<ol class=\"fig-list\">\n<li><strong>Timer-Aktualisierung (Phasen-Dekrementierung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Dekrement von <code>cyclicMsgResumeCounter</code>, sofern <code>FrTSynImmediateTimeSync == TRUE</code> und Zähler $> 0$.</li>\n<li>Dekrement von <code>debounceCounter</code>, sofern <code>FrTSynGlobalTimeDebounceTime &gt; 0</code> und Zähler $> 0$.</li>\n<li>Dekrement von <code>cyclicCounter</code>, sofern <code>FrTSynGlobalTimeTxPeriod &gt; 0</code> und Zähler $> 0$.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Übertragungsstatus-Prüfung (<code>Timesync Message for Time Domain pending?</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfad <code>[ongoing and not completed yet]</code>:</strong> Vorherige Nachricht wartet noch auf Bestätigung (<code>no tx confirmation received</code>) $\\rightarrow$ Direkter Abbruch/Exit des Zyklus, keine Neuübertragung zulässig.</li>\n<li><strong>Pfad <code>[transmission completed]</code>:</strong> Letzte PDU wurde bestätigt:</li>\n<li><em>Fall Immediate Transmission war erfolgreich:</em></li>\n<li>Setze <code>cyclicMsgResumeCounter[TimeDomain] = FrTSynCyclicMsgResumeTime</code>.</li>\n<li>Setze <code>cyclicCounter[TimeDomain] = 0</code>.</li>\n<li>Setze <code>debounceCounter[TimeDomain] = FrTSynGlobalTimeDebounceTime</code>.</li>\n<li><em>Fall Cyclic Transmission war erfolgreich:</em></li>\n<li>Setze <code>debounceCounter[TimeDomain] = FrTSynGlobalTimeDebounceTime</code>.</li>\n<li><strong>Pfad <code>[no transmission ongoing]</code>:</strong> Führt direkt zur Sende-Evaluierung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Arbitrierung & Sendeentscheidung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Entprellsperre:</strong> Prüfung <code>debounceCounter[TimeDomain] == 0?</code></li>\n<li>Wenn <code>[no]</code> $\\rightarrow$ Ende.</li>\n<li><strong>Ereignisgesteuerte Übertragung (Immediate):</strong> Prüfung <code>FrTSynImmediateTimeSync == TRUE?</code></li>\n<li>Wenn <code>[yes]</code>: Prüfung auf Statuswechsel via <code>(timeBaseUpdateCounter geändert) &amp;&amp; (timeBaseStatus &amp; GLOBAL_TIME_BASE)</code>:</li>\n<li>Bei Erfüllung: Aufruf <code>Transmit Immediate Sync/OFS Message</code> $\\rightarrow$ Ende.</li>\n<li>Bei Nicht-Erfüllung: Prüfung <code>cyclicMsgResumeCounter[TimeDomain] == 0?</code>. Ist dieser $> 0$, wird der Zyklus beendet.</li>\n<li><strong>Periodische Übertragung (Cyclic):</strong></li>\n<li>Ausgeführt, wenn <code>FrTSynImmediateTimeSync == FALSE</code> oder wenn bei aktivem Immediate-Modus kein Update anlag und <code>cyclicMsgResumeCounter == 0</code> erreicht ist.</li>\n<li>Bedingung: <code>(FrTSynGlobalTimeTxPeriod &gt; 0) &amp;&amp; (cyclicCounter[TimeDomain] == 0) &amp;&amp; (timeBaseStatus[timeBaseId] &amp; GLOBAL_TIME_BASE)</code>.</li>\n<li>Bei Erfüllung:</li>\n<li>Aufruf <code>Transmit Cyclic Sync/OFS Message</code>.</li>\n<li>Reset des Intervalls: <code>cyclicCounter[TimeDomain] = FrTSynGlobalTimeTxPeriod</code>.</li>\n<li>Andernfalls $\\rightarrow$ Ende ohne Sendeaufruf.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Priorisierung & Starvation-Vermeidung:</strong> Immediate-Übertragungen besitzen strikte Priorität vor zyklischen Nachrichten. Die Entprellzeit (<code>FrTSynGlobalTimeDebounceTime</code>) verhindert Busüberlastungen bei hochfrequenten StbM-Updates.</li>\n<li><strong>Resume-Mechanismus:</strong> Durch das Setzen von <code>cyclicCounter = 0</code> und Laden von <code>cyclicMsgResumeCounter</code> nach einer Sofortübertragung wird verhindert, dass direkt im Folgezyklus eine redundante periodische Botschaft versendet wird.</li>\n<li><strong>Statusabhängigkeit:</strong> Beide Sendepfade sind hard an das Flag <code>GLOBAL_TIME_BASE</code> in <code>timeBaseStatus</code> gekoppelt. Fehlt dieser Status (z. B. lokaler Master hat Synchronisation verloren), wird die Transmission unterdrückt.</li>\n<li><strong>Treiber- und PDU-Verhalten:</strong> Da ein unvollständiger Sendevorgang (<code>pending</code>) jeden neuen Trigger blockiert, muss die Tx-Bestätigung über die untere Schicht (<code>FrIf_TxConfirmation</code>) deterministisch und vor Ablauf des nächsten Periodenfensters erfolgen; Timeouts führen andernfalls zum Stillstand der Master-Sendeaktivität.</li>\n</ul>"}, {"id": "FIG-384066e17fa1d853", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, BSW-Modul <code>FrTSyn</code> (FlexRay Time Synchronization, Spezifikation <em>AUTOSAR_CP_SWS_TimeSyncOverFlexRay</em>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der zyklischen Sende-Arbitrierungslogik innerhalb der Master-Funktion (<code>FrTSyn_MainFunction</code>). Steuert die zeitliche Entprellung, Bestätigungsverarbeitung sowie die Entscheidung zwischen ereignisgesteuerter (<em>Immediate</em>) und periodischer (<em>Cyclic</em>) Übertragung von Synchronisations-Nachrichten (<code>SYNC</code>) pro Time Domain auf den FlexRay-Bus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Modulgrenzen:</strong></li>\n<li><strong>FrTSyn Time Master:</strong> Führende Instanz des Zustands-/Aktivitätsablaufs.</li>\n<li><strong>StbM (Synchronized Time-Base Manager):</strong> Bereitsteller der Master-Zeitbasis über <code>timeBaseStatus</code> und <code>timeBaseUpdateCounter</code>.</li>\n<li><strong>FrIf / FlexRay-Treiber:</strong> Untere Schicht zur PDU-Aussendung und Rückmeldung (<code>TxConfirmation</code>).</li>\n<li><strong>Konfigurationsparameter (statisch / BSW-Konfiguration):</strong></li>\n<li><code>FrTSynImmediateTimeSync</code> (<code>Boolean</code>): Aktiviert die ereignisbasierte Sofort-Übertragung bei Zeitbasis-Updates.</li>\n<li><code>FrTSynGlobalTimeDebounceTime</code> (<code>uint16</code>/<code>uint32</code>): Mindestabstand (Entprellzeit in MainFunction-Ticks) zwischen zwei Sendevorgängen.</li>\n<li><code>FrTSynGlobalTimeTxPeriod</code> (<code>uint16</code>/<code>uint32</code>): Zykluszeit für die periodische Synchronisation.</li>\n<li><code>FrTSynCyclicMsgResumeTime</code> (<code>uint16</code>/<code>uint32</code>): Wartezeit nach einer Sofortaussendung vor Reaktivierung des zyklischen Sendeintervalls.</li>\n<li><strong>Laufzeitvariablen (instanziiert pro <code>TimeDomain</code> / <code>timeBaseId</code>):</strong></li>\n<li><code>cyclicMsgResumeCounter[TimeDomain]</code>: Zähler für die Aussetzzeit des zyklischen Sendens.</li>\n<li><code>debounceCounter[TimeDomain]</code>: Sperrzähler zur Busentlastung.</li>\n<li><code>cyclicCounter[TimeDomain]</code>: Dekrementierender Zähler der regulären Zykluszeit.</li>\n<li><code>timeBaseUpdateCounter[timeBaseId]</code>: Vom StbM inkrementierter Änderungszähler.</li>\n<li><code>timeBaseStatus[timeBaseId]</code>: Bitmaske der Zeitbasis, ausgewertet auf das Flag <code>GLOBAL_TIME_BASE</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf entspricht einem Zyklus der <code>FrTSyn_MainFunction</code> für eine spezifische <code>TimeDomain</code>:</p>\n<ol class=\"fig-list\">\n<li><strong>Timer-Aktualisierung (Phasen-Dekrementierung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Dekrement von <code>cyclicMsgResumeCounter</code>, sofern <code>FrTSynImmediateTimeSync == TRUE</code> und Zähler $> 0$.</li>\n<li>Dekrement von <code>debounceCounter</code>, sofern <code>FrTSynGlobalTimeDebounceTime &gt; 0</code> und Zähler $> 0$.</li>\n<li>Dekrement von <code>cyclicCounter</code>, sofern <code>FrTSynGlobalTimeTxPeriod &gt; 0</code> und Zähler $> 0$.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Übertragungsstatus-Prüfung (<code>Timesync Message for Time Domain pending?</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfad <code>[ongoing and not completed yet]</code>:</strong> Vorherige Nachricht wartet noch auf Bestätigung (<code>no tx confirmation received</code>) $\\rightarrow$ Direkter Abbruch/Exit des Zyklus, keine Neuübertragung zulässig.</li>\n<li><strong>Pfad <code>[transmission completed]</code>:</strong> Letzte PDU wurde bestätigt:</li>\n<li><em>Fall Immediate Transmission war erfolgreich:</em></li>\n<li>Setze <code>cyclicMsgResumeCounter[TimeDomain] = FrTSynCyclicMsgResumeTime</code>.</li>\n<li>Setze <code>cyclicCounter[TimeDomain] = 0</code>.</li>\n<li>Setze <code>debounceCounter[TimeDomain] = FrTSynGlobalTimeDebounceTime</code>.</li>\n<li><em>Fall Cyclic Transmission war erfolgreich:</em></li>\n<li>Setze <code>debounceCounter[TimeDomain] = FrTSynGlobalTimeDebounceTime</code>.</li>\n<li><strong>Pfad <code>[no transmission ongoing]</code>:</strong> Führt direkt zur Sende-Evaluierung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Arbitrierung & Sendeentscheidung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Entprellsperre:</strong> Prüfung <code>debounceCounter[TimeDomain] == 0?</code></li>\n<li>Wenn <code>[no]</code> $\\rightarrow$ Ende.</li>\n<li><strong>Ereignisgesteuerte Übertragung (Immediate):</strong> Prüfung <code>FrTSynImmediateTimeSync == TRUE?</code></li>\n<li>Wenn <code>[yes]</code>: Prüfung auf Statuswechsel via <code>(timeBaseUpdateCounter geändert) &amp;&amp; (timeBaseStatus &amp; GLOBAL_TIME_BASE)</code>:</li>\n<li>Bei Erfüllung: Aufruf <code>Transmit Immediate SYNC Message</code> $\\rightarrow$ Ende.</li>\n<li>Bei Nicht-Erfüllung: Prüfung <code>cyclicMsgResumeCounter[TimeDomain] == 0?</code>. Ist dieser $> 0$, wird der Zyklus beendet.</li>\n<li><strong>Periodische Übertragung (Cyclic):</strong></li>\n<li>Ausgeführt, wenn <code>FrTSynImmediateTimeSync == FALSE</code> oder wenn bei aktivem Immediate-Modus kein Update anlag und <code>cyclicMsgResumeCounter == 0</code> erreicht ist.</li>\n<li>Bedingung: <code>(FrTSynGlobalTimeTxPeriod &gt; 0) &amp;&amp; (cyclicCounter[TimeDomain] == 0) &amp;&amp; (timeBaseStatus[timeBaseId] &amp; GLOBAL_TIME_BASE)</code>.</li>\n<li>Bei Erfüllung:</li>\n<li>Aufruf <code>Transmit Cyclic SYNC Message</code>.</li>\n<li>Reset des Intervalls: <code>cyclicCounter[TimeDomain] = FrTSynGlobalTimeTxPeriod</code>.</li>\n<li>Andernfalls $\\rightarrow$ Ende ohne Sendeaufruf.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Priorisierung & Starvation-Vermeidung:</strong> Immediate-Übertragungen besitzen strikte Priorität vor zyklischen Nachrichten. Die Entprellzeit (<code>FrTSynGlobalTimeDebounceTime</code>) verhindert Busüberlastungen bei hochfrequenten StbM-Updates.</li>\n<li><strong>Resume-Mechanismus:</strong> Durch das Setzen von <code>cyclicCounter = 0</code> und Laden von <code>cyclicMsgResumeCounter</code> nach einer Sofortübertragung wird verhindert, dass direkt im Folgezyklus eine redundante periodische Botschaft versendet wird.</li>\n<li><strong>Statusabhängigkeit:</strong> Beide Sendepfade sind hard an das Flag <code>GLOBAL_TIME_BASE</code> in <code>timeBaseStatus</code> gekoppelt. Fehlt dieser Status (z. B. lokaler Master hat Synchronisation verloren), wird die Transmission unterdrückt.</li>\n<li><strong>Treiber- und PDU-Verhalten:</strong> Da ein unvollständiger Sendevorgang (<code>pending</code>) jeden neuen Trigger blockiert, muss die Tx-Bestätigung über die untere Schicht (<code>FrIf_TxConfirmation</code>) deterministisch und vor Ablauf des nächsten Periodenfensters erfolgen; Timeouts führen andernfalls zum Stillstand der Master-Sendeaktivität.</li>\n</ul>"}], "trans": [{"from": "FIG-75971e761f72195b", "to": "FIG-384066e17fa1d853", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Entfall von Offset-Nachrichten (OFS):</strong> Die Aktivitätsknoten und Verzweigungen zur Nachrichtenverarbeitung beziehen sich nicht mehr auf kombinierte <code>SYNC/OFS</code>-Nachrichten, sondern ausschließlich auf <code>SYNC</code>-Nachrichten (<code>Immediate SYNC Message Transmission for Time Domain successful?</code>, <code>Cyclic SYNC Message Transmission for Time Domain successful?</code>, <code>Transmit Immediate SYNC Message</code>, <code>Transmit Cyclic SYNC Message</code>).</li>\n<li><strong>Diagrammrahmen:</strong> Der UML-Aktivitätsrahmen mit dem Bezeichner <code>act FrTSyn Time Master Timesync Message Transmission</code> wurde entfernt.</li>\n<li><strong>Bedingungssyntax:</strong> In der Dekrementierungsbedingung des Debounce-Counters wurde die Zählervariable zusätzlich geklammert (<code>(debounceCounter[TimeDomain]) &gt; 0</code>).</li>\n</ul>"}]};
